import{_ as s,o as e,c as t,a2 as i}from"./chunks/framework.BhPFG2sY.js";const k=JSON.parse('{"title":"Backend-neutral OPA drop-in for KAOS ext_authz","description":"","frontmatter":{},"headers":[],"relativePath":"security/opa-drop-in/README.md","filePath":"security/opa-drop-in/README.md"}'),n={name:"security/opa-drop-in/README.md"};function o(l,a,h,r,p,d){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="backend-neutral-opa-drop-in-for-kaos-ext-authz" tabindex="-1">Backend-neutral OPA drop-in for KAOS ext_authz <a class="header-anchor" href="#backend-neutral-opa-drop-in-for-kaos-ext-authz" aria-label="Permalink to &quot;Backend-neutral OPA drop-in for KAOS ext_authz&quot;">​</a></h1><p>KAOS resource-level authorization is enforced at the Envoy gateway through an <code>ext_authz</code> gRPC backend. By default that backend is the AIB access-check service, but the integration is <strong>backend-neutral</strong>: the gateway speaks the standard <code>envoy.service.auth.v3.Authorization/Check</code> contract and passes the resource and action as neutral Envoy context extensions (<code>kaos.resource</code> / <code>kaos.action</code>) plus the gateway-validated actor token. Any backend that implements the same contract — for example <a href="https://www.openpolicyagent.org/docs/latest/envoy-introduction/" target="_blank" rel="noreferrer">OPA via opa-envoy</a> — can be dropped in <strong>with configuration only</strong>, without any Envoy or KAOS code change.</p><p>This sample demonstrates that swap.</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>kaos_authz.rego</code></td><td>Rego policy deciding <code>allow</code>/<code>deny</code> from <code>kaos.resource</code> / <code>kaos.action</code> + the actor token <code>sub</code>, mirroring AIB permission-set coverage.</td></tr><tr><td><code>kaos_grants.json</code></td><td>Grant data bundle (actor → granted resources/actions). In production this is sourced from the same grants the broker projects.</td></tr><tr><td><code>opa-envoy.yaml</code></td><td><code>opa-system</code> namespace, a ConfigMap with the policy + data, and an <code>opa-envoy</code> Deployment/Service exposing the ext_authz gRPC plugin on <code>:9191</code>.</td></tr></tbody></table><h2 id="how-the-swap-works-configuration-only" tabindex="-1">How the swap works (configuration only) <a class="header-anchor" href="#how-the-swap-works-configuration-only" aria-label="Permalink to &quot;How the swap works (configuration only)&quot;">​</a></h2><p>The operator generates the <code>SecurityPolicy.spec.extAuth.grpc.backendRef</code> from a single configuration value — the ext_authz backend host:port. Pointing it at opa-envoy instead of AIB is a config change:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CLI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kaos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --auth-enabled</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --ext-authz-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opa-envoy.opa-system.svc.cluster.local:9191</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or Helm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kaos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kaos/kaos-operator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> security.agentAuth.extAuthzUrl=opa-envoy.opa-system.svc.cluster.local:9191</span></span></code></pre></div><p>No Envoy configuration, generated-policy shape, or KAOS code changes — only the backend reference. This is locked by <code>TestConstructSecurityPolicyBackendRefIsConfigDriven</code> in <code>operator/pkg/security/securitypolicy_test.go</code>, which asserts the generated <code>extAuth.grpc.backendRef</code> follows the configured URL for both the default AIB backend and the opa-envoy backend.</p><h2 id="validate-in-kind" tabindex="-1">Validate in KIND <a class="header-anchor" href="#validate-in-kind" aria-label="Permalink to &quot;Validate in KIND&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Deploy the opa-envoy ext_authz backend.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/security/opa-drop-in/opa-envoy.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opa-system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/opa-envoy</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Point KAOS at it (config only) and enable auth.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kaos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --auth-enabled</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --ext-authz-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opa-envoy.opa-system.svc.cluster.local:9191</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. A granted edge is allowed, an ungranted one is denied — equivalently to AIB.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    (agent \`demo/researcher\` is granted \`call\` on \`mcpserver/demo/github\` only.)</span></span></code></pre></div><p>A request whose actor/resource/action matches a grant in <code>kaos_grants.json</code> returns an Envoy <code>OkHttpResponse</code>; anything else is denied — the same allow/deny outcome the AIB access-check produces, proving the contract is backend-neutral.</p><p>AIB remains the default authorization backend; OPA is a validated optional drop-in only.</p>`,13)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
